import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { recordAudit } from "./audit-service";
import { DeductionService } from "./deduction-service";

/**
 * Payroll reconciliation (spec #49).
 *
 * Employers upload the actual payroll result for a salary period. The system
 * compares it with the expected loan deductions generated by the deduction
 * engine and classifies every employee as matched, under-deducted,
 * over-deducted or missing.
 *
 * Actual deductions are stored on `salary_records.loan_deductions`, which is
 * the column reserved for payroll loan deductions. Uploads never move money;
 * posting the result to the ledger is a separate, explicit action.
 */

const RECONCILIATION_ROLES = new Set([
  "ORGANIZATION_OWNER",
  "ORGANIZATION_ADMIN",
  "FINANCE_MANAGER",
  "ACCOUNTANT",
  "PAYROLL_OFFICER",
]);

const RECONCILIATION_VIEWERS = new Set([
  ...RECONCILIATION_ROLES,
  "AUDITOR",
  "LOAN_OFFICER",
]);

const TOLERANCE = 0.5;

export type ReconciliationStatus =
  | "MATCHED"
  | "UNDER"
  | "OVER"
  | "MISSING";

export interface ReconciliationRow {
  employeeId: string;
  employeeNumber: string;
  employeeName: string;
  expected: number;
  actual: number;
  difference: number;
  status: ReconciliationStatus;
  overpayment: number;
  hasPayrollRecord: boolean;
  deductionIds: string[];
  pendingDeductionIds: string[];
}

export interface ReconciliationSummary {
  expected: number;
  actual: number;
  difference: number;
  matched: number;
  under: number;
  over: number;
  missing: number;
  exceptions: number;
  overdue: number;
  hasActuals: boolean;
}

export interface ReconciliationResult {
  rows: ReconciliationRow[];
  summary: ReconciliationSummary;
  error?: string;
}

export type ActualDeductionInput = {
  employeeNumber: string;
  actualAmount: number;
};

type SalaryRecordRow = {
  id: string;
  employee_id: string;
  gross_salary: number;
  other_deductions: number;
  loan_deductions: number;
  employees:
    | {
        employee_number: string | null;
        first_name: string | null;
        last_name: string | null;
      }
    | {
        employee_number: string | null;
        first_name: string | null;
        last_name: string | null;
      }[]
    | null;
};

type DeductionRow = {
  id: string;
  employee_id: string;
  expected_amount: number;
  actual_amount: number;
  status: string;
};

function round2(value: number) {
  return Math.round(value * 100) / 100;
}

function unwrap<T>(value: T | T[] | null | undefined): T | null {
  if (!value) return null;
  return Array.isArray(value) ? value[0] ?? null : value;
}

function employeeNameOf(record: SalaryRecordRow | undefined) {
  const employee = unwrap(record?.employees);
  if (!employee) return "Unknown employee";
  return `${employee.first_name ?? ""} ${employee.last_name ?? ""}`.trim() || "Unknown employee";
}

/** Normalise a number that may contain currency symbols or thousands separators. */
function parseAmount(value: string) {
  const cleaned = value
    .replace(/[₦$€£,\s]/g, "")
    .replace(/[()]/g, "")
    .trim();
  if (!cleaned) return 0;
  const amount = Number(cleaned);
  return Number.isFinite(amount) ? amount : NaN;
}

function splitCsvLine(line: string) {
  const cells: string[] = [];
  let current = "";
  let quoted = false;

  for (let index = 0; index < line.length; index += 1) {
    const character = line[index];
    if (character === '"') {
      if (quoted && line[index + 1] === '"') {
        current += '"';
        index += 1;
      } else {
        quoted = !quoted;
      }
    } else if (character === "," && !quoted) {
      cells.push(current);
      current = "";
    } else {
      current += character;
    }
  }

  cells.push(current);
  return cells.map((cell) => cell.trim());
}

/**
 * Parse an uploaded CSV with an employee identifier column and an actual
 * deduction column. A header row is optional; when present, column names are
 * detected instead of relying on position.
 */
export function parseActualDeductionsCsv(text: string):
  | { rows: ActualDeductionInput[] }
  | { error: string } {
  const lines = text
    .replace(/^\uFEFF/, "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);

  if (lines.length === 0) return { error: "The uploaded file is empty" };

  let employeeIndex = 0;
  let amountIndex = 1;
  let start = 0;

  const header = splitCsvLine(lines[0]).map((cell) => cell.toLowerCase());
  const looksLikeHeader = header.some((cell) =>
    /employee|staff|amount|deduct/.test(cell)
  );

  if (looksLikeHeader) {
    employeeIndex = header.findIndex((cell) =>
      /employee|staff/.test(cell)
    );
    amountIndex = header.findIndex(
      (cell) =>
        /(actual|deduct|loan)/.test(cell) && !/expected|gross|net/.test(cell)
    );
    if (employeeIndex === -1 || amountIndex === -1) {
      return {
        error:
          "Could not find the employee and actual deduction columns. Use headers employee_number,actual_deduction.",
      };
    }
    start = 1;
  }

  const rows: ActualDeductionInput[] = [];
  for (let index = start; index < lines.length; index += 1) {
    const cells = splitCsvLine(lines[index]);
    if (cells.length <= Math.max(employeeIndex, amountIndex)) {
      return { error: `Row ${index + 1} does not have enough columns` };
    }

    const employeeNumber = cells[employeeIndex].trim();
    if (!employeeNumber) {
      return { error: `Row ${index + 1} is missing an employee number` };
    }

    const actualAmount = parseAmount(cells[amountIndex]);
    if (!Number.isFinite(actualAmount) || actualAmount < 0) {
      return {
        error: `Row ${index + 1} has an invalid deduction amount "${cells[amountIndex]}"`,
      };
    }

    rows.push({ employeeNumber, actualAmount: round2(actualAmount) });
  }

  if (rows.length === 0) return { error: "No data rows found in the file" };

  return { rows };
}

export class PayrollReconciliationService {
  private supabase: Awaited<ReturnType<typeof createClient>>;
  private orgId: string | null = null;
  private userId: string | null = null;
  private role: string | null = null;

  private constructor(supabase: Awaited<ReturnType<typeof createClient>>) {
    this.supabase = supabase;
  }

  static async create() {
    const supabase = await createClient();
    const {
      data: { user },
    } = await supabase.auth.getUser();

    const service = new PayrollReconciliationService(supabase);
    if (!user) return service;

    const admin = createAdminClient();
    const { data: profile } = await admin
      .from("user_profiles")
      .select("organization_id, role")
      .eq("user_id", user.id)
      .maybeSingle();

    service.userId = user.id;
    service.orgId = profile?.organization_id ?? null;
    service.role = profile?.role ?? null;

    return service;
  }

  canView() {
    return Boolean(this.orgId && this.role && RECONCILIATION_VIEWERS.has(this.role));
  }

  canManage() {
    return Boolean(this.orgId && this.role && RECONCILIATION_ROLES.has(this.role));
  }

  private async loadPeriod(periodId: string) {
    if (!this.orgId) return null;
    const { data } = await this.supabase
      .from("salary_periods")
      .select("id, name, status, start_date, end_date, payment_date")
      .eq("id", periodId)
      .eq("organization_id", this.orgId)
      .maybeSingle();
    return data;
  }

  async getReconciliation(periodId: string): Promise<ReconciliationResult> {
    const empty: ReconciliationResult = {
      rows: [],
      summary: {
        expected: 0,
        actual: 0,
        difference: 0,
        matched: 0,
        under: 0,
        over: 0,
        missing: 0,
        exceptions: 0,
        overdue: 0,
        hasActuals: false,
      },
    };

    if (!this.orgId) return { ...empty, error: "No organization found" };
    if (!this.canView()) return { ...empty, error: "Unauthorized" };

    const period = await this.loadPeriod(periodId);
    if (!period) return { ...empty, error: "Salary period not found" };

    const [salaryResult, deductionResult] = await Promise.all([
      this.supabase
        .from("salary_records")
        .select(
          `
          id, employee_id, gross_salary, other_deductions, loan_deductions,
          employees:employee_id(employee_number, first_name, last_name)
        `
        )
        .eq("salary_period_id", periodId)
        .eq("organization_id", this.orgId),
      this.supabase
        .from("deduction_records")
        .select("id, employee_id, expected_amount, actual_amount, status")
        .eq("salary_period_id", periodId)
        .eq("organization_id", this.orgId)
        .eq("deduction_type", "LOAN")
        .neq("status", "WAIVED"),
    ]);

    const payrollRecords = (salaryResult.data ?? []) as unknown as SalaryRecordRow[];
    const deductions = (deductionResult.data ?? []) as DeductionRow[];

    const payrollByEmployee = new Map(
      payrollRecords.map((record) => [record.employee_id, record])
    );
    const deductionsByEmployee = new Map<string, DeductionRow[]>();
    for (const deduction of deductions) {
      const list = deductionsByEmployee.get(deduction.employee_id) ?? [];
      list.push(deduction);
      deductionsByEmployee.set(deduction.employee_id, list);
    }

    const employeeIds = new Set([
      ...payrollByEmployee.keys(),
      ...deductionsByEmployee.keys(),
    ]);

    const rows: ReconciliationRow[] = [];
    const summary: ReconciliationSummary = {
      expected: 0,
      actual: 0,
      difference: 0,
      matched: 0,
      under: 0,
      over: 0,
      missing: 0,
      exceptions: 0,
      overdue: 0,
      hasActuals: false,
    };

    for (const employeeId of employeeIds) {
      const payroll = payrollByEmployee.get(employeeId);
      const employeeDeductions = deductionsByEmployee.get(employeeId) ?? [];

      const expected = round2(
        employeeDeductions.reduce(
          (sum, row) => sum + (Number(row.expected_amount) || 0),
          0
        )
      );
      const processed = round2(
        employeeDeductions.reduce(
          (sum, row) => sum + (Number(row.actual_amount) || 0),
          0
        )
      );
      const reported = round2(Number(payroll?.loan_deductions) || 0);
      // Prefer the uploaded payroll figure. Fall back to deductions already
      // processed in-app so reconciled periods are not flagged as missing.
      const actual = reported > 0 ? reported : processed;

      if (expected === 0 && actual === 0) continue;
      if (reported > 0) summary.hasActuals = true;

      let status: ReconciliationStatus;
      if (expected > 0 && actual === 0) {
        status = "MISSING";
      } else if (Math.abs(actual - expected) <= TOLERANCE) {
        status = "MATCHED";
      } else if (actual < expected) {
        status = "UNDER";
      } else {
        status = "OVER";
      }

      const difference = round2(actual - expected);
      rows.push({
        employeeId,
        employeeNumber: unwrap(payroll?.employees)?.employee_number ?? "",
        employeeName: employeeNameOf(payroll),
        expected,
        actual,
        difference,
        status,
        overpayment: difference > 0 ? difference : 0,
        hasPayrollRecord: Boolean(payroll),
        deductionIds: employeeDeductions.map((row) => row.id),
        pendingDeductionIds: employeeDeductions
          .filter((row) => row.status === "PENDING")
          .map((row) => row.id),
      });

      summary.expected = round2(summary.expected + expected);
      summary.actual = round2(summary.actual + actual);
      summary.difference = round2(summary.actual - summary.expected);

      switch (status) {
        case "MATCHED":
          summary.matched += 1;
          break;
        case "UNDER":
          summary.under += 1;
          summary.exceptions += 1;
          break;
        case "OVER":
          summary.over += 1;
          summary.exceptions += 1;
          break;
        case "MISSING":
          summary.missing += 1;
          summary.exceptions += 1;
          break;
      }

      if (status === "MISSING") {
        summary.overdue += 1;
      }
    }

    rows.sort((a, b) => {
      if (a.status === b.status) return a.employeeName.localeCompare(b.employeeName);
      const priority: Record<ReconciliationStatus, number> = {
        MISSING: 0,
        UNDER: 1,
        OVER: 2,
        MATCHED: 3,
      };
      return priority[a.status] - priority[b.status];
    });

    return { rows, summary };
  }

  /**
   * Persist the uploaded payroll result. Only employees whose salary has been
   * imported for the period can be reconciled; unknown employee numbers and
   * employees without a payroll record are reported back to the user.
   */
  async importActuals(periodId: string, rows: ActualDeductionInput[]) {
    if (!this.canManage() || !this.userId) return { error: "Unauthorized" };
    if (rows.length === 0) return { error: "No rows to import" };

    const period = await this.loadPeriod(periodId);
    if (!period) return { error: "Salary period not found" };

    const [employeeResult, salaryResult] = await Promise.all([
      this.supabase
        .from("employees")
        .select("id, employee_number, first_name, last_name")
        .eq("organization_id", this.orgId),
      this.supabase
        .from("salary_records")
        .select("id, employee_id, gross_salary, other_deductions")
        .eq("salary_period_id", periodId)
        .eq("organization_id", this.orgId),
    ]);

    const employeeByNumber = new Map(
      (employeeResult.data ?? []).map((employee) => [
        String(employee.employee_number ?? "").trim().toLowerCase(),
        employee,
      ])
    );
    const payrollByEmployee = new Map(
      (salaryResult.data ?? []).map((record) => [record.employee_id, record])
    );

    const unknown: string[] = [];
    const noPayroll: string[] = [];
    const updated: {
      employeeNumber: string;
      employeeName: string;
      actualAmount: number;
    }[] = [];

    for (const row of rows) {
      const key = row.employeeNumber.trim().toLowerCase();
      const employee = employeeByNumber.get(key);
      if (!employee) {
        unknown.push(row.employeeNumber);
        continue;
      }

      const payroll = payrollByEmployee.get(employee.id);
      if (!payroll) {
        noPayroll.push(
          `${employee.first_name ?? ""} ${employee.last_name ?? ""}`.trim() ||
            row.employeeNumber
        );
        continue;
      }

      const gross = Number(payroll.gross_salary) || 0;
      const other = Number(payroll.other_deductions) || 0;
      const { error } = await this.supabase
        .from("salary_records")
        .update({
          loan_deductions: row.actualAmount,
          net_salary: round2(gross - other - row.actualAmount),
          updated_at: new Date().toISOString(),
        })
        .eq("id", payroll.id)
        .eq("organization_id", this.orgId);

      if (error) return { error: error.message };

      updated.push({
        employeeNumber: employee.employee_number ?? row.employeeNumber,
        employeeName: `${employee.first_name ?? ""} ${employee.last_name ?? ""}`.trim(),
        actualAmount: row.actualAmount,
      });
    }

    if (updated.length === 0) {
      return {
        error:
          unknown.length > 0
            ? `No matching employees. Unknown employee numbers: ${unknown.join(", ")}`
            : "No employee has a payroll record for this period. Import salaries first.",
        unknown,
        noPayroll,
      };
    }

    const totalActual = round2(
      updated.reduce((sum, row) => sum + row.actualAmount, 0)
    );

    await recordAudit({
      organizationId: this.orgId,
      userId: this.userId,
      action: "payroll.reconciled",
      entityType: "salary_period",
      entityId: periodId,
      after: {
        periodName: period.name,
        uploadedRows: rows.length,
        updatedRows: updated.length,
        totalActual,
        unknown,
        noPayroll,
        rows: updated,
      },
    });

    return {
      success: `Reconciled ${updated.length} employee${
        updated.length === 1 ? "" : "s"
      } · ${totalActual.toLocaleString("en-NG", {
        style: "currency",
        currency: "NGN",
        maximumFractionDigits: 2,
      })} reported`,
      updated: updated.length,
      totalActual,
      unknown,
      noPayroll,
    };
  }

  /**
   * Post the reconciled amounts through the deduction engine. This updates
   * schedules, repayment records and the ledger; over-deductions are capped at
   * the amount owed to the lending fund, with the excess reported separately.
   */
  async applyReconciliation(periodId: string) {
    if (!this.canManage() || !this.userId) return { error: "Unauthorized" };

    const result = await this.getReconciliation(periodId);
    if (result.error) return { error: result.error };

    const applicable = result.rows.filter(
      (row) =>
        row.status !== "MISSING" &&
        row.actual > 0 &&
        row.pendingDeductionIds.length > 0
    );

    if (applicable.length === 0) {
      return {
        success: "Nothing to post — all reconciled deductions are already processed",
        processed: 0,
        skipped: 0,
        totalApplied: 0,
      };
    }

    const deductionService = await DeductionService.create();
    let processed = 0;
    let skipped = 0;
    let totalApplied = 0;
    const errors: string[] = [];

    for (const row of applicable) {
      const eligible = row.deductionIds.filter((id) =>
        row.pendingDeductionIds.includes(id)
      );

      let allocated = 0;
      for (let index = 0; index < eligible.length; index += 1) {
        const deductionId = eligible[index];
        const isLast = index === eligible.length - 1;

        // Re-read the expected amount so multi-loan employees are allocated
        // proportionally without needing a second aggregate query.
        const { data } = await this.supabase
          .from("deduction_records")
          .select("expected_amount, status")
          .eq("id", deductionId)
          .eq("organization_id", this.orgId ?? "")
          .maybeSingle();

        if (!data || data.status !== "PENDING") {
          skipped += 1;
          continue;
        }

        const expected = Number(data.expected_amount) || 0;
        const share = isLast
          ? round2(Math.min(expected, row.actual - allocated))
          : round2(Math.min(expected, row.actual * (expected / row.expected)));

        if (share <= 0) {
          skipped += 1;
          continue;
        }

        const outcome = await deductionService.processDeduction(
          deductionId,
          share
        );
        if (outcome.error) {
          errors.push(`${row.employeeName}: ${outcome.error}`);
          skipped += 1;
          continue;
        }

        processed += 1;
        allocated = round2(allocated + share);
        totalApplied = round2(totalApplied + share);
      }
    }

    if (processed === 0 && errors.length === 0) {
      return {
        success: "Nothing to post — all reconciled deductions are already processed",
        processed: 0,
        skipped,
        totalApplied: 0,
        errors,
      };
    }

    await recordAudit({
      organizationId: this.orgId,
      userId: this.userId,
      action: "payroll.reconciliation_applied",
      entityType: "salary_period",
      entityId: periodId,
      after: {
        processed,
        skipped,
        totalApplied,
        errors,
      },
    });

    if (errors.length > 0) {
      return {
        error: `Posted ${processed} deduction${
          processed === 1 ? "" : "s"
        }, skipped ${skipped}. ${errors.join("; ")}`,
        processed,
        skipped,
        totalApplied,
        errors,
      };
    }

    return {
      success: `Posted ${processed} deduction${
        processed === 1 ? "" : "s"
      } · ${totalApplied.toLocaleString("en-NG", {
        style: "currency",
        currency: "NGN",
        maximumFractionDigits: 2,
      })}`,
      processed,
      skipped,
      totalApplied,
      errors,
    };
  }

  async exportReconciliationCSV(periodId: string): Promise<string> {
    const result = await this.getReconciliation(periodId);
    const header =
      "Employee Number,Employee Name,Expected,Actual,Difference,Status\n";
    const body = result.rows
      .map((row) =>
        [
          this.csvEscape(row.employeeNumber),
          this.csvEscape(row.employeeName),
          row.expected,
          row.actual,
          row.difference,
          row.status,
        ].join(",")
      )
      .join("\n");
    return header + body;
  }

  async exportReconciliationTemplate(periodId: string): Promise<string> {
    const result = await this.getReconciliation(periodId);
    const header = "employee_number,actual_deduction\n";
    const body = result.rows
      .map((row) =>
        [this.csvEscape(row.employeeNumber), row.expected].join(",")
      )
      .join("\n");
    return header + body;
  }

  private csvEscape(value: string) {
    return /[",\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
  }
}
